"""Read/write src/data/imported.js – the app's bank of extracted MCQs."""
from __future__ import annotations

import json
import re
from pathlib import Path

HEADER = (
    "// Generated by tools/extractor (python -m merident_extract mcq ... --merge).\n"
    "// Extracted MCQs merged into the MeriDent Prep question bank. Edit with care; re-run the tool to add more.\n"
)
FIRST_ID = 5001  # NEET MDS seed bank = 1–70, ADC = 1001+, imported = 5001+

DEFAULT_PATH = Path(__file__).resolve().parents[3] / "src" / "data" / "imported.js"


def load(path: Path | None = None) -> list[dict]:
    path = Path(path or globals()['DEFAULT_PATH'])
    if not path.exists():
        return []
    m = re.search(r"export const IMPORTED_MCQS = (\[.*\])\s*;?\s*$", path.read_text(encoding="utf-8"), re.S)
    return json.loads(m.group(1)) if m else []


def save(rows: list[dict], path: Path | None = None) -> None:
    path = Path(path or globals()['DEFAULT_PATH'])
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(HEADER + "export const IMPORTED_MCQS = " + json.dumps(rows, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")


def merge(new_rows: list[dict], path: Path | None = None) -> tuple[int, int]:
    path = Path(path or globals()['DEFAULT_PATH'])
    """Append rows not already present (by fingerprint). Re-numbers ids after the current max. Returns (added, skipped)."""
    bank = load(path)
    seen = {r.get("fingerprint") for r in bank}
    next_id = max([FIRST_ID - 1] + [r["id"] for r in bank]) + 1
    added = 0
    for r in new_rows:
        if r["fingerprint"] in seen:
            continue
        bank.append({**r, "id": next_id})
        seen.add(r["fingerprint"])
        next_id += 1
        added += 1
    save(bank, path)
    return added, len(new_rows) - added
